package edu.academic.hotel;
import java.time.*; import java.time.temporal.ChronoUnit; import java.math.*; import java.util.*;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException;
@Service public class ReservationService {
 private final CustomerRepository customers; private final RoomRepository rooms; private final BookingRepository bookings;
 public ReservationService(CustomerRepository c,RoomRepository r,BookingRepository b){customers=c;rooms=r;bookings=b;}
 public RoomView view(Room r){return new RoomView(r.id,r.roomNumber,r.roomType,r.description,r.capacity,r.pricePerNight,r.imageUrl,new ListString(r.amenities==null?List.of():Arrays.asList(r.amenities.split(","))),r.active);}
 public CustomerView view(Customer c){return new CustomerView(c.id,c.fullName,c.email,c.phoneNumber);}
 public BookingView view(Booking b){return new BookingView(b.id,b.bookingReference,view(b.customer),view(b.room),b.checkInDate,b.checkOutDate,b.numberOfGuests,b.totalPrice,b.bookingStatus,b.createdAt,b.updatedAt);}
 public List<RoomView> listRooms(String type,BigDecimal max){return rooms.findAll().stream().filter(r->r.active&&(type==null||r.roomType.equalsIgnoreCase(type))&&(max==null||r.pricePerNight.compareTo(max)<=0)).map(this::view).toList();}
 public RoomView room(Long id){return view(rooms.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Room not found")));}
 public List<RoomView> available(LocalDate in,LocalDate out,int guests,String type){validateDates(in,out);if(guests<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Guests must be at least one");return rooms.findAvailable(in,out,guests,type,null).stream().map(this::view).toList();}
 @Transactional public CustomerView createCustomer(CustomerRequest q){if(customers.findByEmailIgnoreCase(q.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");try{return view(customers.saveAndFlush(new Customer(q.fullName(),q.email(),q.phoneNumber())));}catch(org.springframework.dao.DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");}}
 public CustomerView customer(Long id){return view(customers.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found")));}
 @Transactional public BookingView book(BookingRequest q){validateDates(q.checkInDate(),q.checkOutDate());Room room=rooms.lockById(q.roomId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Room not found"));if(!room.active)throw new ResponseStatusException(HttpStatus.CONFLICT,"Room is inactive");if(q.numberOfGuests()>room.capacity)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Guest count exceeds room capacity");if(rooms.findAvailable(q.checkInDate(),q.checkOutDate(),q.numberOfGuests(),null,null).stream().noneMatch(x->x.id.equals(room.id)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Room is not available for those dates");Customer c=customers.findByEmailIgnoreCase(q.email()).orElseGet(()->customers.save(new Customer(q.fullName(),q.email(),q.phoneNumber())));Booking b=new Booking();b.bookingReference("HR-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());b.customer=c;b.room=room;b.checkInDate=q.checkInDate();b.checkOutDate=q.checkOutDate();b.numberOfGuests=q.numberOfGuests();b.totalPrice=room.pricePerNight.multiply(BigDecimal.valueOf(ChronoUnit.DAYS.between(q.checkInDate(),q.checkOutDate())));return view(bookings.save(b));}
 public List<BookingView> all(){return bookings.findAllByOrderByCreatedAtDesc().stream().map(this::view).toList();}
 public BookingView booking(String ref){return view(find(ref));}
 @Transactional public BookingView cancel(String ref){Booking b=find(ref);if(b.bookingStatus==BookingStatus.CANCELLED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Booking already cancelled");if(b.bookingStatus==BookingStatus.COMPLETED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Completed bookings cannot be cancelled");b.bookingStatus=BookingStatus.CANCELLED;b.updatedAt=Instant.now();return view(b);}
 @Transactional public BookingView status(String ref,BookingStatus s){Booking b=find(ref);if(b.bookingStatus!=BookingStatus.CONFIRMED||s!=BookingStatus.COMPLETED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only confirmed bookings may be marked completed; use cancel endpoint to cancel");b.bookingStatus=s;b.updatedAt=Instant.now();return view(b);}
 private Booking find(String ref){return bookings.findByBookingReference(ref).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));}
 private static void validateDates(LocalDate in,LocalDate out){if(in==null||out==null||in.isBefore(LocalDate.now())||!out.isAfter(in))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Check-in must be today or later and check-out must follow check-in");}
}

